create or replace function public.svc_layer1_evidence_descriptor(p_evidence_id uuid,p_source_id uuid) returns jsonb language plpgsql security definer set search_path='public','pipeline','pg_temp' as $$ declare v jsonb; begin if coalesce(auth.role(),'') <> 'service_role' then raise exception 'service_role required'; end if; select jsonb_build_object('id',e.id,'source_id',e.source_id,'storage_path',e.storage_path,'content_hash',e.content_hash,'mime_type',e.mime_type,'metadata',e.metadata,'captured_at',e.captured_at) into v from pipeline.evidence_artifacts e where e.id=p_evidence_id and e.source_id=p_source_id; if v is null then raise exception 'evidence/source mismatch'; end if; return v; end $$;
revoke all on function public.svc_layer1_evidence_descriptor(uuid,uuid) from public,anon,authenticated;
grant execute on function public.svc_layer1_evidence_descriptor(uuid,uuid) to service_role;
